<?php
namespace App\Controllers\Api\V1;
use App\Models\{ContentGroupModel,NoticeModel,SelectableOptionModel,StudyAreaModel,SubjectModel,TopicModel};
final class CatalogController extends ApiController
{
    private function ownsNotice($id):bool{return (bool)(new NoticeModel())->where(['id'=>$id,'user_id'=>$this->userId()])->first();}
    private function ownedSubject($id):?array{return (new SubjectModel())->select('subjects.*')->join('notices','notices.id=subjects.notice_id')->where(['subjects.id'=>$id,'notices.user_id'=>$this->userId(),'notices.deleted_at'=>null])->first();}
    private function ownedTopic($id):?array{return (new TopicModel())->select('topics.*')->join('subjects','subjects.id=topics.subject_id')->join('notices','notices.id=subjects.notice_id')->where(['topics.id'=>$id,'notices.user_id'=>$this->userId(),'notices.deleted_at'=>null])->first();}
    public function createSubject($noticeId){if(!$this->ownsNotice($noticeId))return $this->failNotFound();$d=$this->body();$name=trim($d['name']??'');if($name==='')return $this->failValidationErrors('Informe o nome da matéria.');$gm=new ContentGroupModel();$group=$gm->where(['notice_id'=>$noticeId,'external_ref'=>'manual-general'])->first();$groupId=$group['id']??$gm->insert(['notice_id'=>$noticeId,'external_ref'=>'manual-general','name'=>'Conhecimentos gerais','knowledge_type'=>'general','applies_to_all'=>true],true);$id=(new SubjectModel())->insert(['notice_id'=>$noticeId,'content_group_id'=>$groupId,'name'=>$name,'weight'=>max(0,min(100,(int)($d['weight']??5))),'color'=>max(1,min(6,(int)($d['color']??1)))],true);return $this->respondCreated(['id'=>$id]);}
    public function updateArea($noticeId,$areaId){if(!$this->ownsNotice($noticeId))return $this->failNotFound();$am=new StudyAreaModel();$area=$am->where(['id'=>$areaId,'notice_id'=>$noticeId])->first();if(!$area)return $this->failNotFound();if($area['knowledge_type']==='general')return $this->failValidationErrors('Conhecimentos gerais são obrigatórios.');$selected=filter_var($this->body()['selected']??false,FILTER_VALIDATE_BOOL);$am->update($areaId,['is_selected'=>$selected]);return $this->respondUpdated(['id'=>$areaId,'selected'=>$selected]);}
    public function updateOption($noticeId,$optionId){if(!$this->ownsNotice($noticeId))return $this->failNotFound();$om=new SelectableOptionModel();if(!$om->where(['id'=>$optionId,'notice_id'=>$noticeId])->first())return $this->failNotFound();$selected=filter_var($this->body()['selected']??false,FILTER_VALIDATE_BOOL);$om->update($optionId,['is_selected'=>$selected]);return $this->respondUpdated(['id'=>$optionId,'selected'=>$selected]);}
    public function updateSubject($id){if(!$this->ownedSubject($id))return $this->failNotFound();$body=$this->body();$d=array_intersect_key($body,array_flip(['name','weight','color','sort_order']));if(isset($body['nome']))$d['name']=$body['nome'];if(isset($body['peso']))$d['weight']=$body['peso'];(new SubjectModel())->update($id,$d);return $this->respondUpdated($d);}
    public function deleteSubject($id){if(!$this->ownedSubject($id))return $this->failNotFound();(new SubjectModel())->delete($id);return $this->respondDeleted();}
    public function createTopic($subjectId){if(!$this->ownedSubject($subjectId))return $this->failNotFound();$d=$this->body();$name=trim($d['name']??'');if($name==='')return $this->failValidationErrors('Informe o nome do tópico.');$id=(new TopicModel())->insert(['subject_id'=>$subjectId,'name'=>$name,'difficulty'=>max(0,min(10,(int)($d['difficulty']??10)))],true);return $this->respondCreated(['id'=>$id]);}
    public function updateTopic($id){if(!$this->ownedTopic($id))return $this->failNotFound();$body=$this->body();$d=array_intersect_key($body,array_flip(['name','difficulty','sort_order']));if(isset($body['nome']))$d['name']=$body['nome'];if(isset($body['dificuldade']))$d['difficulty']=$body['dificuldade'];(new TopicModel())->update($id,$d);return $this->respondUpdated($d);}
    public function deleteTopic($id){if(!$this->ownedTopic($id))return $this->failNotFound();(new TopicModel())->delete($id);return $this->respondDeleted();}
}
